typedef enum {
    Z_IOERROR_TAG_NOTFOUND,
    Z_IOERROR_TAG_PERMISSIONDENIED,
    Z_IOERROR_TAG_INTERRUPTED,
    Z_IOERROR_TAG_INVALIDPATH,
    Z_IOERROR_TAG_EOF,
    Z_IOERROR_TAG_BADENCODING,
    Z_IOERROR_TAG_EXISTS,
    Z_IOERROR_TAG_ISDIR,
    Z_IOERROR_TAG_NOTDIR,
    Z_IOERROR_TAG_NOSPACE,
    Z_IOERROR_TAG_OTHER,
} z_t673_tag_t;
typedef struct {
    z_t673_tag_t tag;
    void* data;
} z_t673_t;
static void z_t673_destroy(z_t673_t* u) {
    if (!u) return;
    if (!u->data) return;
    switch (u->tag) {
        case Z_IOERROR_TAG_INVALIDPATH:
            z_t52_free((z_t52_t*)u->data);
            free(u->data);
            break;
        case Z_IOERROR_TAG_OTHER:
            z_t52_free((z_t52_t*)u->data);
            free(u->data);
            break;
        default: break;
    }
}

